-- Operations 接入支付风控配置与执行发布：Platform 注册数据（2026-10-15 阶段 3 评审稿，待执行文件）
-- 目标库：Platform Support 业务库（本机 mor_platform_e2e / mor-test mor_platform）；手工执行需单独授权，应用启动不会执行。
-- 字符集：用 mysql --default-character-set=utf8mb4 执行；latin1 客户端会把中文写成乱码。
-- 150 行 INSERT；0 UPDATE / DELETE；不新增 Gateway Target，不改表结构。
-- 新路由与菜单资源为 DISABLED，PLATFORM_ADMIN 授权为 REVOKED；激活另见 activation-local.sql（本机）与阶段 6 的环境激活文件。
-- ID 段 9000000000001010xx～9000000000001043xx 在仓库既有注册 SQL 中未使用；执行前仍按下方预检核对目标库无冲突。
-- 本文件不含 COMMIT：核对插入行数后手工 COMMIT，任何不符则 ROLLBACK。
SET @prc_time=UTC_TIMESTAMP(6);
SET @prc_admin=(SELECT role_id FROM t_role WHERE role_code='PLATFORM_ADMIN' AND scope_key='PLATFORM' AND system_role=1 AND status='ACTIVE');
SET @prc_read=(SELECT permission_id FROM t_permission WHERE permission_code='RISK_DECISION_CONFIG_READ' AND status='ACTIVE');
SET @prc_parent=(SELECT resource_id FROM t_console_resource WHERE resource_code='OPERATIONS_RISK_MANAGEMENT' AND channel='OPERATIONS' AND status='ACTIVE');
SET @prc_target=(SELECT target_id FROM t_gateway_target WHERE target_service_code='operations-console-bff' AND channel='OPERATIONS' AND status='ACTIVE');
SELECT @prc_admin admin_role_id,@prc_read read_permission_id,@prc_parent risk_menu_id,@prc_target target_id;
-- 预检：四个值均非空；以下计数均应为 0，否则停止。
SELECT (SELECT COUNT(*) FROM t_permission WHERE permission_id BETWEEN 900000000000101101 AND 900000000000101199 OR permission_code IN ('RISK_LIST_READ','RISK_LIST_MANAGE','RISK_EXECUTION_RELEASE_PREPARE','RISK_EXECUTION_RELEASE_ACTIVATE')) permission_conflicts,
       (SELECT COUNT(*) FROM t_console_resource WHERE resource_id BETWEEN 900000000000101301 AND 900000000000101399 OR resource_code IN ('OPERATIONS_RISK_LISTS','OPERATIONS_RISK_EXECUTION_RELEASES','OPERATIONS_RISK_LIST_MANAGE','OPERATIONS_RISK_EXECUTION_RELEASE_PREPARE','OPERATIONS_RISK_EXECUTION_RELEASE_ACTIVATE')) resource_conflicts,
       (SELECT COUNT(*) FROM t_gateway_route WHERE route_id BETWEEN 900000000000101001 AND 900000000000101099 OR route_code IN ('operations-risk-list-list','operations-risk-list-create','operations-risk-list-entries','operations-risk-list-entry-add','operations-risk-list-entry-deactivate','operations-risk-execution-list','operations-risk-execution-create','operations-risk-execution-detail','operations-risk-execution-validate','operations-risk-execution-shadow-run','operations-risk-execution-activate')) route_conflicts;
START TRANSACTION;








-- 预期影响行数：t_permission 4、t_role_permission 4、t_console_resource 5、t_gateway_route 11、t_gateway_route_header 50、t_gateway_route_query_param 10、t_gateway_guard_rule 66；合计 150。
-- 核对无误后 COMMIT；否则 ROLLBACK。
